import java.util.*;class Solution{public int minTotalDistance(int[][]g){List<Integer>r=new ArrayList<>(),c=new ArrayList<>();for(int i=0;i<g.length;i++)for(int j=0;j<g[0].length;j++)if(g[i][j]==1)r.add(i);for(int j=0;j<g[0].length;j++)for(int i=0;i<g.length;i++)if(g[i][j]==1)c.add(j);int mr=r.get(r.size()/2),mc=c.get(c.size()/2),s=0;for(int x:r)s+=Math.abs(x-mr);for(int x:c)s+=Math.abs(x-mc);return s;}}
